#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 8          /* maximum number of vertices */
#define MAXE 8          /* maximum number of edges accepted */

static int adj[MAXV][MAXV];   /* adjacency matrix, 0 = no edge, 1 = edge */
static int color[MAXV];      /* 0 = unvisited, 1 = visiting, 2 = visited */
static char found_cycle;     /* non‑zero if a cycle has been found */

/* Depth‑first search that stops as soon as a cycle is discovered. */
static void dfs(int v)
{
    int w;

    if (found_cycle)               /* early exit if a cycle is already known */
        return;

    color[v] = 1;                  /* mark as “visiting” */

    for (w = 0; w < MAXV; ++w) {
        if (!adj[v][w])            /* no edge v→w */
            continue;

        if (color[w] == 0) {       /* tree edge */
            dfs(w);
            if (found_cycle)       /* propagate early exit */
                return;
        } else if (color[w] == 1) {/* back edge → cycle */
            found_cycle = 1;
            return;
        }
        /* colour 2 (already finished) is ignored */
    }

    color[v] = 2;                  /* mark as “finished” */
}

int main(int argc, char **argv)
{
    int i, u, v;
    int edge_cnt = 0;

    /* Input validation: arguments must come in pairs */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    for (i = 1; i < argc; i += 2) {
        char *endptr;
        long val;

        /* first vertex */
        val = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0' || val < 0 || val > MAXV - 1) {
            puts("INVALID_INPUT");
            return 0;
        }
        u = (int)val;

        /* second vertex */
        val = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0' || val < 0 || val > MAXV - 1) {
            puts("INVALID_INPUT");
            return 0;
        }
        v = (int)val;

        if (edge_cnt >= MAXE) {        /* too many edges */
            puts("INVALID_INPUT");
            return 0;
        }

        adj[u][v] = 1;                 /* store the directed edge */
        ++edge_cnt;
    }

    memset(color, 0, sizeof(color));
    found_cycle = 0;

    for (i = 0; i < MAXV; ++i) {
        if (color[i] == 0)
            dfs(i);
        if (found_cycle)
            break;
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
